using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation configuration for telemetry, quality, and compare modes.
/// </summary>
internal static class EvalConfiguration
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates a reporting configuration that stores results locally for comparison.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfiguration(
        IChatClient chatClient,
        string scenarioName)
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new CompletenessEvaluator(),
        };

        var storage = new DiskBasedReportingStorage(StoragePath);

        return new ReportingConfiguration(
            chatClient,
            evaluators,
            storage,
            scenarioName: scenarioName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: captures and validates that agent interactions produce
/// expected telemetry signals (token usage, latency, tool calls).
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static IChatClient CreateChatClient()
    {
        return new ChatClientBuilder()
            .UseFunctionInvocation()
            .UseOpenTelemetry()
            .Use(new AzureAIInferenceChatClient(
                new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                    ?? "https://localhost"),
                Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key",
                "gpt-4o-mini"));
    }

    [TestMethod]
    public async Task Agent_Response_Produces_Token_Usage()
    {
        var client = CreateChatClient();

        var response = await client.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response.Usage, "Token usage telemetry should be present.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Input tokens should be recorded.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Output tokens should be recorded.");
    }

    [TestMethod]
    public async Task Agent_Response_Contains_FinishReason()
    {
        var client = CreateChatClient();

        var response = await client.GetResponseAsync("Say hello.");

        Assert.IsNotNull(response.Messages);
        Assert.IsTrue(response.Messages.Count > 0, "Response should contain messages.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates agent responses for coherence, relevance,
/// fluency, and completeness using LLM-as-judge evaluators.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IChatClient CreateJudgeClient()
    {
        return new AzureAIInferenceChatClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key",
            "gpt-4o-mini");
    }

    [TestMethod]
    public async Task Coach_Response_Meets_Quality_Threshold()
    {
        var judgeClient = CreateJudgeClient();
        var config = EvalConfiguration.CreateReportingConfiguration(judgeClient, "quality-baseline");

        await using var scenario = await config.CreateScenarioRunAsync("coach-greeting");

        // Simulate agent response
        var agentResponse = new ChatMessage(
            ChatRole.Assistant,
            "Hello! I'm your coaching assistant. How can I help you today?");

        var context = new EvaluationContext
        {
            ["query"] = "Greet the user",
            ["response"] = agentResponse.Text!,
        };

        var results = await scenario.EvaluateAsync(context);

        foreach (var (name, result) in results)
        {
            if (result is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Quality metric '{name}' scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    [TestMethod]
    public async Task Coach_Detailed_Response_Is_Complete()
    {
        var judgeClient = CreateJudgeClient();
        var config = EvalConfiguration.CreateReportingConfiguration(judgeClient, "quality-completeness");

        await using var scenario = await config.CreateScenarioRunAsync("coach-advice");

        var agentResponse = new ChatMessage(
            ChatRole.Assistant,
            "To improve your productivity, consider: 1) Time-blocking your calendar, " +
            "2) Using the Pomodoro technique, 3) Setting clear daily priorities, and " +
            "4) Minimizing context switching between tasks.");

        var context = new EvaluationContext
        {
            ["query"] = "Give me productivity tips",
            ["response"] = agentResponse.Text!,
        };

        var results = await scenario.EvaluateAsync(context);

        if (results.TryGetValue(nameof(CompletenessEvaluator), out var completeness)
            && completeness is NumericMetric score)
        {
            Assert.IsTrue(score.Value >= 4.0,
                $"Completeness scored {score.Value}, expected >= 4.0");
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenarios across different configurations
/// and stores results side-by-side for regression detection.
/// </summary>
[TestClass]
public class CompareTests
{
    private static IChatClient CreateJudgeClient()
    {
        return new AzureAIInferenceChatClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key",
            "gpt-4o-mini");
    }

    [TestMethod]
    public async Task Compare_Baseline_Vs_Current()
    {
        var judgeClient = CreateJudgeClient();

        // Tag identifies the run; compare results across tags.
        var runTag = Environment.GetEnvironmentVariable("EVAL_RUN_TAG") ?? "dev";

        var config = EvalConfiguration.CreateReportingConfiguration(
            judgeClient,
            $"compare-{runTag}");

        await using var scenario = await config.CreateScenarioRunAsync("coach-question");

        var agentResponse = new ChatMessage(
            ChatRole.Assistant,
            "Based on your recent progress, I recommend focusing on " +
            "consistency rather than intensity for the next two weeks.");

        var context = new EvaluationContext
        {
            ["query"] = "What should I focus on next?",
            ["response"] = agentResponse.Text!,
        };

        var results = await scenario.EvaluateAsync(context);

        // Store results; comparison is done via the reporting tool.
        foreach (var (name, result) in results)
        {
            if (result is NumericMetric metric)
            {
                // Log for local comparison
                Console.WriteLine($"[{runTag}] {name}: {metric.Value:F2}");
            }
        }
    }

    [TestMethod]
    public async Task Generate_Comparison_Report()
    {
        var storagePath = Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

        if (!Directory.Exists(storagePath))
        {
            Assert.Inconclusive("No prior results to compare. Run Compare_Baseline_Vs_Current first.");
            return;
        }

        var storage = new DiskBasedReportingStorage(storagePath);
        var scenarios = await storage.ReadLatestScenarioRunsAsync(count: 2);

        Assert.IsTrue(scenarios.Count >= 1,
            "At least one prior run is needed to generate a comparison report.");

        Console.WriteLine($"Found {scenarios.Count} scenario run(s) available for comparison.");
        foreach (var run in scenarios)
        {
            Console.WriteLine($"  - Scenario: {run.ScenarioName}, Timestamp: {run.Timestamp}");
        }
    }
}

